"""Build class.html (the classroom version) from index.html (the lecturers version).

The only difference: on slide 2 the board snapshot links to the live 3D board.
Edit index.html, then run:  python3 make_class.py
"""
import re, pathlib

BOARD_URL = "https://lukori.github.io/territories/"
here = pathlib.Path(__file__).parent
src = (here / "index.html").read_text(encoding="utf-8")

block = re.compile(r"  <!-- BOARD-LINK:.*?<!-- /BOARD-LINK -->", re.S)
assert block.search(src), "BOARD-LINK markers not found in index.html"

linked = (
    "  <!-- classroom version: generated by make_class.py from index.html – do not edit by hand -->\n"
    f'  <a class="snap" href="{BOARD_URL}" target="_blank" rel="noopener" title="פתיחת הלוח">\n'
    '    <img src="img/miro3d.jpg" alt="הלוח בתלת־ממד: טריטוריות על צירי דיגיטלי–פיזי, מחקרי–יישומי ומשחקי">\n'
    "  </a>"
)
(here / "class.html").write_text(block.sub(linked, src), encoding="utf-8")
print("class.html written")
